    public function install(){$this->load->model('extension/module/probg_services');$this->model_extension_module_probg_services->install();$this->load->model('user/user_group');foreach(array('extension/module/probg_services','extension/module/probg_services_block','extension/probg_services/category','extension/probg_services/service','extension/probg_services/enquiry') as $route){$this->model_user_user_group->addPermission($this->user->getGroupId(),'access',$route);$this->model_user_user_group->addPermission($this->user->getGroupId(),'modify',$route);}}
