    protected function validate(){if(!$this->user->hasPermission('modify','extension/module/probg_services'))$this->error['warning']=$this->language->get('error_permission');$limit=(int)($this->request->post['module_probg_services_limit']??0);if($limit<1||$limit>100)$this->error['limit']=$this->language->get('error_limit');$count=(int)($this->request->post['module_probg_services_rate_limit_count']??0);$minutes=(int)($this->request->post['module_probg_services_rate_limit_minutes']??0);$files=(int)($this->request->post['module_probg_services_upload_max_files']??0);$mb=(int)($this->request->post['module_probg_services_upload_max_mb']??0);$days=(int)($this->request->post['module_probg_services_retention_days']??0);if($count<1||$count>100||$minutes<1||$minutes>1440||$files<0||$files>10||$mb<1||$mb>25||$days<1)$this->error['security']=$this->language->get('error_security');return !$this->error;}
